import { Injectable, computed, signal, inject } from '@angular/core';
import { UserdashboardService } from './userdashboard.service';
import { UserCaseData, TicketAlert, SessionData } from '../../interfaces/userdashboard.interface';
import { UserDetail } from '../../../core/interfaces/login.interface';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { SocketService } from '../../../core/services/socket/socket.service';
import { ErrorHandlerUtil } from '../../utility/error-handler.util';
import { MULTI_DEVICE_EXEMPT_CASE_ID, MULTI_DEVICE_SESSION_KEY } from '../../../core/utility/commonfunction.service';

interface DashboardState {
    cases: UserCaseData[];
    sessions: SessionData[];
    tickets: TicketAlert[];
    loading: boolean;
    page: number;
    hasMore: boolean;
    userProfile: UserDetail | null;
    error: string | null;
}

@Injectable({
    providedIn: 'root'
})
export class UserDashboardFacade {
    // Services
    private readonly api = inject(UserdashboardService);
    private readonly storage = inject(SecureStorageService);
    private readonly socket = inject(SocketService);

    // State (Signals)
    private readonly state = signal<DashboardState>({
        cases: [],
        sessions: [],
        tickets: [],
        loading: true,
        page: 1,
        hasMore: true,
        userProfile: null,
        error: null
    });

    // Selectors (Computed)
    readonly cases = computed(() => this.state().cases);
    readonly loading = computed(() => this.state().loading);
    readonly hasMore = computed(() => this.state().hasMore);
    readonly userProfile = computed(() => this.state().userProfile);
    readonly error = computed(() => this.state().error);
    readonly isRealtimeUser = computed(() =>
        this.state().cases.some(c => !c.jPermission?.includes('RT'))
    );

    constructor() {
        this.setupSocketListeners();
    }

    // Actions
    async initDashboard() {
        this.updateState({ loading: true, error: null });
        try {
            console.log('🔄 Initializing dashboard...');
            const userProfile = await this.storage.getUserInfo();
            console.log('👤 User profile loaded:', userProfile);
            this.updateState({ userProfile });

            await this.loadPage(1, true); // Reset and load page 1
            console.log('✅ Dashboard loaded successfully');
            this.loadDashboardInfo(); // Background load additional info
        } catch (error) {
            console.error('❌ Dashboard initialization error:', error);
            this.handleError(error, 'Error initializing dashboard');
        } finally {
            this.updateState({ loading: false });
        }
    }

    async loadMore() {
        const currentState = this.state();
        console.log('📜 loadMore triggered. Page:', currentState.page, 'Loading:', currentState.loading, 'HasMore:', currentState.hasMore);
        if (currentState.loading || !currentState.hasMore) return;

        this.updateState({ loading: true });
        try {
            console.log('🔄 Loading page:', currentState.page + 1);
            await this.loadPage(currentState.page + 1, false);
        } catch (error) {
            this.handleError(error, 'Error loading more cases');
        } finally {
            this.updateState({ loading: false });
        }
    }

    private async loadPage(page: number, reset: boolean) {
        const newCases = await this.api.getDashboardlist(page);
        console.log(`✅ Page ${page} loaded. Items:`, newCases.length);

        this.updateState(state => ({
            cases: reset ? newCases : [...state.cases, ...newCases],
            page: page,
            hasMore: newCases.length > 0,
            // Re-apply internal updates if needed (tickets/sessions mapping logic moved here)
        }));

        // Set multi-device login flag if exempt case is in user's case list
        const allCases = reset ? newCases : [...this.state().cases];
        if (allCases.some(c => c.nCaseid === MULTI_DEVICE_EXEMPT_CASE_ID)) {
            localStorage.setItem(MULTI_DEVICE_SESSION_KEY, 'true');
        }

        // Trigger post-load updates
        this.mapSessionsToCases();
        this.mapTicketsToCases();
    }

    private async loadDashboardInfo() {
        try {
            const dashInfo = await this.api.getDashInfo();
            if (dashInfo?.length) {
                // dashInfo[1] seems to be sessions based on legacy code
                const sessions = dashInfo[1] ?? [];
                this.updateState({ sessions });
                this.mapSessionsToCases();
            }
        } catch (error) {
            console.error('Error loading dashboard info', error); // Non-blocking
        }
    }

    // Business Logic Helpers
    private mapSessionsToCases() {
        const { cases, sessions } = this.state();
        if (!sessions.length) return;

        const updatedCases = cases.map(c => {
            const session = sessions.find(s => s.nCaseid === c.nCaseid);
            return session ? { ...c, nSesid: session.nSesid } : c;
        });

        this.updateState({ cases: updatedCases });
    }

    private mapTicketsToCases() {
        const { cases, tickets } = this.state();
        // Logic from legacy: updateTickets() -> GetTicketCount(a)
        // If ticketList is empty, this might essentially do nothing, but keeping structure.
        if (!tickets.length) return;

        const updatedCases = cases.map(c => {
            const ticket = tickets.find(t => t.nCaseid === c.nCaseid);
            return ticket ? { ...c, ticketCount: ticket.totaltickets } : c;
        });

        this.updateState({ cases: updatedCases });
    }

    // Socket Handling
    private setupSocketListeners() {
        this.socket.getNotification().subscribe(() => {
            // On notification, refresh dashboard
            // Legacy code called initDashBoardInfo() which resets everything.
            // We might want to be smarter, but sticking to legacy behavior for now.
            this.initDashboard();
        });
    }

    // Updates
    updateTicketCount(caseId: string, count: number) {
        const { tickets } = this.state();
        const existingIndex = tickets.findIndex(t => t.nCaseid === caseId);

        let newTickets = [...tickets];
        if (existingIndex > -1) {
            newTickets[existingIndex] = { ...newTickets[existingIndex], totaltickets: count };
        } else {
            newTickets.push({ nCaseid: caseId, totaltickets: count });
        }

        this.updateState({ tickets: newTickets });
        this.mapTicketsToCases();
    }

    resetState() {
      this.state.set({
        cases: [],
        sessions: [],
        tickets: [],
        loading: true,
        page: 1,
        hasMore: true,
        userProfile: null,
        error: null
      });
    }

    // Utility
    private updateState(partialState: Partial<DashboardState> | ((current: DashboardState) => Partial<DashboardState>)) {
        this.state.update(current => {
            const updates = typeof partialState === 'function' ? partialState(current) : partialState;
            return { ...current, ...updates };
        });
    }

    private handleError(error: any, context: string) {
        const msg = `${context}: ${ErrorHandlerUtil.getErrorMessage(error)}`;
        this.updateState({ error: msg });
        console.error(msg);
        // Ideally use a global notification service here
    }
}