import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { SecureStorageService } from '../storage/secure-storage.service';
import { AuthValidationService } from '../auth-validation/auth-validation.service';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { UserdashboardService } from '../../../userpanel/services/user-dashboard/userdashboard.service';
import { UserDashboardFacade } from '../../../userpanel/services/user-dashboard/user-dashboard.facade';
import { HeaderService } from '../header/header.service';
import { CasedetailService } from '../../../shared/services/casedetail/casedetail.service';
import { RealtimeFacade } from '../../../rt/facades/realtime.facade';
import { CommonfunctionService, MULTI_DEVICE_SESSION_KEY } from '../../utility/commonfunction.service';
import { MyfileService } from '../../../shared/services/myfile/myfile.service';
import { CacheService } from '../cache/cache.service';

@Injectable({
  providedIn: 'root'
})
export class LogoutService {

  private dashboardService = inject(UserdashboardService);
  private dashboardFacade = inject(UserDashboardFacade);
  private headerService = inject(HeaderService);
  private casedetailService = inject(CasedetailService);
  private realtimeFacade = inject(RealtimeFacade);
  private cf = inject(CommonfunctionService);
  private myfileService = inject(MyfileService);
  private cacheService = inject(CacheService);

  constructor(
    private http: HttpClient,
    public sStore: SecureStorageService,
    private authValidation: AuthValidationService
  ) {
  }

  async logout(): Promise<boolean> {
    const mdl: any = { cBroweserid: this.sStore.getStorage('browserid') };
    try {
      await firstValueFrom(
        this.http.post<any>(
          `${environment.cloudUrl}${environment.authservice}/auth/signout`,
          mdl
        )
      );
    } catch (err) {
      // API call may fail but we still need to clear local state
    }
    this.authValidation.clearCache();
    localStorage.removeItem(MULTI_DEVICE_SESSION_KEY);
    this.sStore.logOut();

    // Clear all service caches to prevent stale data on next login
    this.dashboardService.invalidateCache();
    this.dashboardFacade.resetState();
    this.headerService.resetState();
    this.casedetailService.resetState();
    this.realtimeFacade.resetState();
    this.cf.resetState();
    this.myfileService.resetState();
    this.cacheService.delete();

    return true;
  }
}
